package android.widget;import android.content.Context;public class CompoundButton extends Button{public interface OnCheckedChangeListener{void onCheckedChanged(CompoundButton b,boolean v);}private OnCheckedChangeListener listener;private boolean checked;public CompoundButton(Context c){super(c);}public void setChecked(boolean v){boolean old=checked;checked=v;if(old!=v&&listener!=null)listener.onCheckedChanged(this,v);}public boolean isChecked(){return checked;}public void setOnCheckedChangeListener(OnCheckedChangeListener l){listener=l;} }